func within(hits []time.Time, window time.Duration, now time.Time) (n int, oldest time.Time) {
	for _, t := range hits {
		if t.After(now.Add(-window)) {
			if n == 0 || t.Before(oldest) {
				oldest = t
			}
			n++
		}
	}
	return n, oldest
}

